#ifndef COMMON_H
#define COMMON_H

#include <stdbool.h>

#define exit_with_code(code) { result = code; goto _exit; }


bool compile_files(
    YR_COMPILER* compiler,
    int argc,
    const char** argv)
{
  for (int i = 0; i < argc - 1; i++)
  {
    FILE* rule_file;
    const char* ns;
    const char* file_name;
    char* colon = (char*) strchr(argv[i], ':');
    int errors;

    // Namespace delimiter must be a colon not followed by a slash or backslash
    if (colon && *(colon + 1) != '\\' && *(colon + 1) != '/')
    {
      file_name = colon + 1;
      *colon = '\0';
      ns = argv[i];
    }
    else
    {
      file_name = argv[i];
      ns = NULL;
    }

    if (strcmp(file_name, "-") == 0)
      rule_file = stdin;
    else
      rule_file = fopen(file_name, "r");

    if (rule_file == NULL)
    {
      fprintf(stderr, "error: could not open file: %s\n", file_name);
      return false;
    }

    errors = yr_compiler_add_file(compiler, rule_file, ns, file_name);

    fclose(rule_file);

    if (errors > 0)
      return false;
  }

  return true;
}


bool is_integer(const char *str)
{
  if (*str == '-')
    str++;

  if (*str == '\0')
    return false;

  while(*str)
  {
    if (!isdigit(*str))
      return false;
    str++;
  }

  return true;
}


bool is_float(const char *str)
{
  bool has_dot = false;

  if (*str == '-')      // skip the minus sign if present
    str++;

  if (*str == '.')      // float can't start with a dot
    return false;

  while(*str)
  {
    if (*str == '.')
    {
      if (has_dot)      // two dots, not a float
        return false;

      has_dot = true;
    }
    else if (!isdigit(*str))
    {
      return false;
    }

    str++;
  }

  return has_dot; // to be float must contain a dot
}

#endif
